with recent_order_items as (select * from order_items where unit_price between 190 and 260 and (product_id in (4, 13, 17, 31) or order_id in (15, 22))), order_items_stats as (select case when unit_price >= 340 then 'high' when unit_price >= 170 then 'mid' else 'low' end as unit_price_bucket, product_id, sum(quantity) as total_quantity, count(*) as total_count from recent_order_items group by case when unit_price >= 340 then 'high' when unit_price >= 170 then 'mid' else 'low' end, product_id) select * from order_items_stats where total_quantity > 18;
